/* DMA 环形缓冲区架构文字描述 */

┌─────────────────────────────────────────────────────────────┐
|                           CPU                             |
|  ┌──────────┐     ┌──────────────────┐                     |
|  │ 应用层   │────▶│ 环形缓冲区 API   │                     |
|  │ (主循环) │     ├──────────────────┤                     |
|  └────┬────┘     │ head/tail 管理   │                     |
|       │          ├──────────────────┤                     |
|       │          │ 空闲/已用计数    │                     |
|       ▼          └──────────────────┘                     |
|            ┌──────────────────────────────────────────┘
|            │ DMA 完成中断 / 半完成中断
|            |
|  ┌──────────────────────────────┐         ┌─────────────┐
|  │ DMA 控制器                   ◄────────►│ 外设寄存器  |
|  │ (USART1 DMA TX/RX)            │         │ (USART1_DR) |
|  └──────────────────────────────┘         └─────────────┘
|                                                       |
|  ┌──────────────────────────────────────────────────┐  |
|  │ 环形缓冲区内存区域 (SRAM)                        |  |
|  │ [0] [1] [2] ... [N-1] ------------------------┘  |
|  │      ↑ head(tail)                                 |
|  └──────────────────────────────────────────────────┘  |

/* 伪代码：环形缓冲区的数据流 */
// DMA 自动执行（无需 CPU 干预）:
//   每当 USART 收到一字节数据:
//       DR -> ring_buffer[head]
//       head = (head + 1) % BUFFER_SIZE
//       if head == tail: set overrun_flag
//       if head >= half_size: trigger half-transfer interrupt

// 服务例程 (DMA Half-Circle Complete):
// 设置事件标志给主任务，唤醒处理任务

// 应用层循环（主任务）:
// 等待 data_available 事件
// while (ring_buffer.available() > 0):
//     byte = ring_buffer.read()
//     process(byte)
// ring_buffer.clear_used()  /* 释放已读空间 */

/* 接口封装（ADT 风格） - 外部只调用这些函数 */
typedef struct {
    uint8_t *buffer;
    size_t head;
    size_t tail;
    size_t size;
    bool overrun_flag;
} RingBuffer_t;

RB_OK_t rb_init(RingBuffer_t *rb, uint8_t *buf, size_t len);
size_t rb_put(RingBuffer_t *rb, uint8_t data);  // DMA 调用
size_t rb_get(RingBuffer_t *rb, uint8_t *data);  // 应用层调用
size_t rb_available(RingBuffer_t *rb);
size_t rb_free_space(RingBuffer_t *rb);
bool rb_overrun_occurred(RingBuffer_t *rb);

/* ============================================================
 * UART_DMA_RINGBUFFER.H
 * STM32F4xx + HAL + DMA 双缓冲环形缓冲区头文件
 * ============================================================ */
#ifndef UART_DMA_RINGBUFFER_H
#define UART_DMA_RINGBUFFER_H

#include <stddef.h>
#include <stdint.h>
#include "stm32f4xx.h"

/* 环形缓冲区配置 */
#define UART_DMA_RINGBUF_HALF_SIZE    512
#define UART_DMA_RINGBUF_TOTAL_SIZE   (UART_DMA_RINGBUF_HALF_SIZE * 2)

typedef enum {
    RB_OK = 0,
    RB_ERR_NULL_PTR,
    RB_ERR_OVERFLOW,
    RB_ERR_EMPTY
} RB_Status_t;

typedef struct {
    uint8_t buffer[UART_DMA_RINGBUF_TOTAL_SIZE];
    size_t head;
    size_t tail;
    size_t dma_half_done;
    USART_HandleTypeDef *huart;
    DMA_HandleTypeDef *hdma_rx;
} UART_DMA_RingBuffer_t;

RB_Status_t UART_DMA_RB_Init(UART_DMA_RingBuffer_t *rb,
                            USART_HandleTypeDef *huart,
                            DMA_HandleTypeDef *hdma);
RB_Status_t UART_DMA_RB_StartReceive(UART_DMA_RingBuffer_t *rb);
RB_Status_t UART_DMA_RB_StopReceive(UART_DMA_RingBuffer_t *rb);
size_t UART_DMA_RB_Read(UART_DMA_RingBuffer_t *rb,
                       uint8_t *out_buf,
                       size_t max_bytes);
size_t UART_DMA_RB_Available(UART_DMA_RingBuffer_t *rb);
bool UART_DMA_RB_HasOverflow(UART_DMA_RingBuffer_t *rb);

#endif

/* ============================================================
 * UART_DMA_RINGBUFFER.C
 * 实现文件
 * ============================================================ */
#include "uart_dma_ringbuffer.h"
#include <string.h>

static size_t rb_calc_available(const UART_DMA_RingBuffer_t *rb) {
    if (rb->head >= rb->tail) {
        return rb->head - rb->tail;
    } else {
        return (UART_DMA_RINGBUF_TOTAL_SIZE - rb->tail) + rb->head;
    }
}

static void rb_consume(UART_DMA_RingBuffer_t *rb, size_t count) {
    rb->tail = (rb->tail + count) % UART_DMA_RINGBUF_TOTAL_SIZE;
}

RB_Status_t UART_DMA_RB_Init(UART_DMA_RingBuffer_t *rb,
                            USART_HandleTypeDef *huart,
                            DMA_HandleTypeDef *hdma_rx) {
    if (!rb || !huart || !hdma_rx) {
        return RB_ERR_NULL_PTR;
    }
    memset(rb, 0, sizeof(UART_DMA_RingBuffer_t));
    rb->head = 0;
    rb->tail = 0;
    rb->dma_half_done = false;
    rb->huart = huart;
    rb->hdma_rx = hdma_rx;
    if (hdma_rx->Init.BufferSize != UART_DMA_RINGBUF_HALF_SIZE) {
        return RB_ERR_OVERFLOW;
    }
    return RB_OK;
}

RB_Status_t UART_DMA_RB_StartReceive(UART_DMA_RingBuffer_t *rb) {
    if (!rb || !rb->huart || !rb->hdma_rx) {
        return RB_ERR_NULL_PTR;
    }
    rb->head = 0;
    rb->tail = 0;
    rb->dma_half_done = false;
    rb->hdma_rx->Instance->CNDTR = UART_DMA_RINGBUF_HALF_SIZE;
    rb->hdma_rx->Init.BufferSize = UART_DMA_RINGBUF_HALF_SIZE;
    HAL_UART_Receive_DMA(rb->huart, rb->buffer, UART_DMA_RINGBUF_HALF_SIZE);
    return RB_OK;
}

RB_Status_t UART_DMA_RB_StopReceive(UART_DMA_RingBuffer_t *rb) {
    if (!rb || !rb->huart) {
        return RB_ERR_NULL_PTR;
    }
    HAL_UART_DisableRX_IT(rb->huart);
    HAL_DMA_Abort(rb->hdma_rx);
    return RB_OK;
}

size_t UART_DMA_RB_Read(UART_DMA_RingBuffer_t *rb,
                       uint8_t *out_buf,
                       size_t max_bytes) {
    if (!rb || !out_buf) return 0;
    size_t available = rb_calc_available(rb);
    if (available == 0) return 0;
    size_t to_copy = (available < max_bytes) ? available : max_bytes;
    size_t head = rb->head;
    size_t tail = rb->tail;
    if (head >= tail) {
        memcpy(out_buf, &rb->buffer[tail], to_copy);
    } else {
        size_t first_part = UART_DMA_RINGBUF_TOTAL_SIZE - tail;
        if (first_part > to_copy) first_part = to_copy;
        memcpy(out_buf, &rb->buffer[tail], first_part);
        memcpy(&out_buf[first_part], rb->buffer, to_copy - first_part);
    }
    rb_consume(rb, to_copy);
    return to_copy;
}

size_t UART_DMA_RB_Available(UART_DMA_RingBuffer_t *rb) {
    if (!rb) return 0;
    return rb_calc_available(rb);
}

bool UART_DMA_RB_HasOverflow(UART_DMA_RingBuffer_t *rb) {
    if (!rb) return false;
    return false;
}

