/* 陷阱演示：Head/Tail 竞态条件的危险模式 */

/* ❌ 错误做法：没有保护头尾更新的竞态条件 */
uint8_t ringbuf[64];
size_t head = 0;  /* DMA 在中断中更新（通过监视 DMA 计数器推算） */
size_t tail = 0;  /* 任务中更新 */

/* DMA 半传输中断中（implicit head update）*/
void DMA_IRQHandler(void) {
    /* HAL 清除中断标志 */
    /* 头隐含前进：head = (head + HALF_SIZE) % 64 */
    /* 但不能直接在这里修改 head，因为可能与 tail 读取竞争 */
    volatile size_t dummy = head;  /* 防止优化 */
}

/* 任务中读取数据 */
void read_task(void) {
    size_t available;
    uint8_t temp[64];

    /* 读取 head 和 tail 之间没有同步 */
    available = calculate_available(head, tail);  /* 危险！head 可能在计算过程中变化 */

    if (available > 0) {
        /* 可能读到不一致的状态 */
        memcpy(temp, &ringbuf[tail], available);
        /* 此时 head 可能已经前进了，导致逻辑错误 */
        tail += available;  /* 基于过时的 available 值更新 */
    }
}

/* ✅ 正确做法：使用临界区保护或原子操作 */
#include "cmsis_compiler.h"

void safe_read_task(void) {
    size_t head, tail, available;
    uint8_t temp[64];
    CRITICAL_START();  /* 禁用中断 */
    head = get_head_from_dma_counter();  /* 从 DMA 计数器推算 */
    tail = ringbuf_tail;                 /* 读取 tail */
    CRITICAL_END();  /* 恢复中断 */

    /* 现在 head 和 tail 是一致的快照 */
    available = calculate_available(head, tail);

    if (available > 0) {
        memcpy(temp, &ringbuf[tail], available);

        /* 再次临界区保护更新 tail */
        CRITICAL_START();
        ringbuf_tail = (tail + available) % RINGBUF_SIZE;
        CRITICAL_END();
    }
}

/* 更佳方案：使用原子指针（Cortex-M7 支持 LDREX/STREX）*/
#include <stdatomic.h>

atomic_size_t atomic_head;
atomic_size_t atomic_tail;

size_t atomic_read(uint8_t *buf, size_t len) {
    size_t head, tail, avail;
    do {
        head = load_atomic(&atomic_head);
        tail = load_atomic(&atomic_tail);
        if (head >= tail) {
            avail = head - tail;
        } else {
            avail = (RINGBUF_SIZE - tail) + head;
        }
        if (avail == 0) return 0;
        if (avail > len) len = avail;
    } while (compare_and_swap(&atomic_tail, tail, tail + len) != 0);
    return len;
}

/* 陷阱：缓存未刷新导致的数据可见性问题 */
/* 在 STM32H7 上，如果 ringbuf 在 DTCM 或 AXI SRAM 中且启用了缓存 */
void hazard_cache_issue(void) {
    /* DMA 写入数据到 ringbuf */
    /* 如果没有 invalidate cache，CPU 读取到的是旧值 */
    __DCache_InvalidateRange((uint32_t)ringbuf, RINGBUF_SIZE);
    /* 现在才能安全读取 */
}

