/* uart_poll_drivers.c - 原始版本 */

#include "stm32f4xx_hal.h"

/* 全局环形缓冲区（简单实现，没有保护） */
#define UART_BUFFER_SIZE  256
uint8_t uart_rx_buffer[UART_BUFFER_SIZE];
size_t buf_head = 0;
size_t buf_tail = 0;
bool buf_new_data = false;

/* 中断服务例程：每收到一个字节触发一次 */
void USART1_IRQHandler(void) {
    if (__HAL_USART_GET_FLAG(&huart1, USART_FLAG_RXNE)) {
        uint8_t data = __HAL_USART_GET_RX_DATA(&huart1);

        /* 危险：没有检查缓冲区是否已满 */
        uart_rx_buffer[buf_head] = data;
        buf_head = (buf_head + 1) % UART_BUFFER_SIZE;

        /* 如果 head 追上了 tail，数据被静默覆盖（丢失） */
        if (buf_head == buf_tail) {
            buf_tail = (buf_tail + 1) % UART_BUFFER_SIZE;
        }

        buf_new_data = true;
    }
}

/* 主循环：轮询检查 */
void main_task(void) {
    if (buf_new_data) {
        buf_new_data = false;

        while (buf_head != buf_tail) {
            uint8_t data = uart_rx_buffer[buf_tail];
            process_byte(data);
            buf_tail = (buf_tail + 1) % UART_BUFFER_SIZE;
        }
    }
}

